{"type":"tool_use","timestamp":1792933223762,"sessionID":"ses_e8cdd3f70ffeC7cHQdRDOP5bkd","part":{"partID":"prt_1732573e6001BV82Gg2eW5Jhtq","sessionID":"ses_e8cdd3f70ffeC7cHQdRDOP5bkd","messageID":"msg_17323ad33001u1wxIb8HPcZHMj","type":"tool","id":"chatcmpl-tool-aa6bdd8694c100ed","tool":"write","state":{"status":"completed","input":{"path":"/private/var/folders/8z/h73xmj297g1995r1d9q6dc2r0000gn/T/vw-eval-ltkecr8l/work/tests/test_bsearch.py","content":""""Unit tests for the bsearch module.

Reported defect: bsearch misses some targets that are actually present.

Root cause: the loop condition ``while lo < hi`` exits as soon as the search
range has narrowed to a single element, so that lone candidate is never
compared to the target and the function falls through to ``return -1``.
Any shape in which the target ends up alone in the final range is hit:
a single-element list, the last of a two-element list, or a target that the
narrowing process isolates (e.g. the last element of a sorted list).

BsearchRegressionTests pins those exact defect-triggering shapes: each one
FAILS against the buggy ``lo < hi`` implementation and PASSES once the loop
condition is corrected to ``lo <= hi``.

BsearchBehaviorTests documents the general contract (a present target
yields a valid index; an absent target yields -1) so the fix cannot
regress normal cases.
"""

import os
import sys
import unittest

# Ensure the worktree root -- where bsearch.py lives -- is importable no
# matter how the suite is launched (unittest discover, module path, pytest).
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from bsearch import bsearch  # noqa: E402


def find(items, target):
    """Convenience wrapper around bsearch.bsearch."""
    return bsearch(items, target)


class BsearchRegressionTests(unittest.TestCase):
    """Present targets that the buggy ``while lo < hi`` loop misses."""

    def test_present_target_in_single_element_list(self):
        # lo == hi on entry: the only element is never compared.
        self.assertEqual(find([7], 7), 0)

    def test_present_target_is_last_of_two_elements(self):
        # lo=0, hi=1 -> mid=0 discards the smaller half,
        # leaving lo == hi == 1 without checking items[1].
        self.assertEqual(find([2, 4], 4), 1)

    def test_present_target_is_last_of_odd_length_list(self):
        # [1, 3, 5, 7, 9]: both halves peel away until lo == hi == 4.
        self.assertEqual(find([1, 3, 5, 7, 9], 9), 4)

    def test_present_target_reaches_lone_element_after_narrowing(self):
        # [1, 3, 5]: mid=1 (3 > 1) sets hi=0, leaving lo == hi == 0 unchecked.
        self.assertEqual(find([1, 3, 5], 1), 0)


class BsearchBehaviorTests(unittest.TestCase):
    """General contract tests for bsearch over a sorted list."""

    def test_empty_list_is_absent(self):
        self.assertEqual(find([], 5), -1)

    def test_single_element_is_absent(self):
        self.assertEqual(find([7], 9), -1)

    def test_target_between_elements_is_absent(self):
        self.assertEqual(find([1, 3, 5], 4), -1)

    def test_target_below_range_is_absent(self):
        self.assertEqual(find([3, 5, 7], 1), -1)

    def test_target_above_range_is_absent(self):
        self.assertEqual(find([3, 5, 7], 10), -1)

    def test_non_integer_absent_target(self):
        self.assertEqual(find([1, 2, 3], 3.5), -1)

    def test_target_at_middle(self):
        self.assertEqual(find([1, 3, 5, 7, 9], 5), 2)

    def test_target_at_first(self):
        self.assertEqual(find([1, 3, 5, 7, 9], 1), 0)

    def test_target_at_last_of_even_length_list(self):
        self.assertEqual(find([1, 3, 5, 7], 7), 3)

    def test_duplicate_values_return_a_valid_index(self):
        items = [2, 2, 2]
        idx = find(items, 2)
        self.assertNotEqual(idx, -1)
        self.assertEqual(items[idx], 2)

    def test_negative_values(self):
        self.assertEqual(find([-9, -4, -1, 3, 8], -4), 1)
        self.assertEqual(find([-9, -4, -1, 3, 8], 8), 4)

    def test_every_position_found_in_larger_list(self):
        items = list(range(100))
        for target in (0, 1, 2, 49, 50, 51, 93, 98, 99):
            with self.subTest(target=target):
                self.assertEqual(find(items, target), target)

    def test_absent_values_in_larger_list(self):
        items = list(range(100))
        for target in (-1, 33.5, 100):
            with self.subTest(target=target):
                self.assertEqual(find(items, target), -1)


if __name__ == "__main__":
    unittest.main()
